package com.campuseventhub;
import java.io.IOException;import java.sql.*;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet("/feedback") public class FeedbackServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("student_id")==null){p.sendRedirect("login.jsp");return;}int eid=Integer.parseInt(r.getParameter("event_id"));p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<!DOCTYPE html><html><head><title>Event Feedback</title><style>body{font-family:Arial;background:#f4f6f8;padding:30px}.box{max-width:550px;margin:auto;background:white;padding:30px;border-radius:12px}select,textarea{width:100%;padding:10px;margin:8px 0 15px}button{width:100%;padding:12px;background:#6f42c1;color:white;border:0;border-radius:6px}</style></head><body><div class='box'><h1>Event Feedback</h1><form method='post' action='feedback'><input type='hidden' name='event_id' value='"+eid+"'><label>Rating</label><select name='rating'><option value='5'>5 - Excellent</option><option value='4'>4 - Very Good</option><option value='3'>3 - Good</option><option value='2'>2 - Average</option><option value='1'>1 - Poor</option></select><label>Your Comment</label><textarea name='comment' rows='6'></textarea><button>Submit Feedback</button></form></div></body></html>");}
 protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("student_id")==null){p.sendRedirect("login.jsp");return;}try(Connection c=DBConnection.getConnection()){PreparedStatement x=c.prepareStatement("INSERT INTO feedback(student_id,event_id,rating,comment,feedback_date) VALUES(?,?,?,?,CURDATE()) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),feedback_date=CURDATE()");x.setInt(1,(Integer)s.getAttribute("student_id"));x.setInt(2,Integer.parseInt(r.getParameter("event_id")));x.setInt(3,Integer.parseInt(r.getParameter("rating")));x.setString(4,r.getParameter("comment"));x.executeUpdate();p.setContentType("text/html;charset=UTF-8");p.getWriter().println("<script>alert('Thank you for your feedback!');window.location='myEvents';</script>");}catch(Exception e){p.getWriter().println("<h2>Error: "+e.getMessage()+"</h2>");}}
}
